const rawResponse = $json.text || '';
const source = $('Load Resume & Preferences').first().json;

const fallbackResume = {
  candidate: { name: 'Krish Rathi' },
  professional: {
    current_title: 'Software Engineer Intern',
    seniority: 'intern',
    years_experience: 1,
    domain: 'Full Stack and AI Engineering'
  },
  skills: {
    technical: [
      'JavaScript', 'TypeScript', 'React', 'Next.js', 'Node.js',
      'Python', 'Gemini AI', 'RAG', 'Firebase', 'AWS', 'Docker'
    ]
  },
  search: {
    suggested_titles: [
      'Software Engineer Intern',
      'Full Stack Developer Intern',
      'Frontend Developer Intern',
      'AI Engineer Intern',
      'Junior Software Engineer'
    ],
    keywords: ['javascript', 'typescript', 'react', 'next.js', 'python', 'ai']
  }
};

let resumeData = fallbackResume;

try {
  let cleaned = rawResponse.trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1) cleaned = cleaned.substring(start, end + 1);
  resumeData = { ...fallbackResume, ...JSON.parse(cleaned) };
} catch (error) {
  console.log('Resume parser fallback used:', error.message);
}

const prefs = source.userPreferences;
const suggestedTitles = resumeData.search?.suggested_titles || [];
const titles = (suggestedTitles.length ? suggestedTitles : fallbackResume.search.suggested_titles).slice(0, 6);
const keywords = (resumeData.search?.keywords || fallbackResume.search.keywords).slice(0, 12);

return [{
  json: {
    resumeData,
    userPreferences: prefs,
    telegramChatId: source.telegramChatId,
    requestId: source.requestId,
    searchConfig: {
      titles,
      keywords,
      locations: prefs.locations,
      primaryQuery: titles[0] || 'Software Engineer Intern',
      locationParam: prefs.locations[0],
      seniority: resumeData.professional?.seniority || 'intern',
      experienceYears: resumeData.professional?.years_experience || 0,
      domain: resumeData.professional?.domain || '',
      jobType: prefs.jobType,
      platforms: prefs.platforms,
      maxJobsForGemini: prefs.maxJobsForGemini || 30
    }
  }
}];

const config = $input.first().json;

return config.searchConfig.platforms.map((platform) => ({
  json: { ...config, currentPlatform: platform }
}));

const wrappers = $input.all().map((item) => item.json);
const context = $('Build Search Config').first().json;
const jobs = [];

const list = (value) => Array.isArray(value) ? value : (value ? [value] : []);
const flat = (value) => list(value).flatMap((item) => Array.isArray(item) ? item : [item]);
const root = (value) => Array.isArray(value) && value.length === 1 ? value[0] : value;
const clean = (value, limit = 900) => String(value || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, limit);
const absolute = (value, base) => {
  if (!value) return '';
  return String(value).startsWith('http') ? String(value) : base + String(value);
};

for (const wrapper of wrappers) {
  const platform = wrapper.platform;
  const response = wrapper.response;

  try {
    if (platform === 'remotive') {
      for (const item of list(root(response)?.jobs)) {
        jobs.push({
          platform: 'Remotive',
          id: String(item.id || item.url),
          title: item.title || '',
          company: item.company_name || '',
          location: item.candidate_required_location || 'Remote',
          description: clean(item.description),
          url: item.url || '',
          salary: item.salary || '',
          posted_date: item.publication_date || '',
          job_type: item.job_type || 'Full-time',
          remote: true,
          required_skills: list(item.tags)
        });
      }
    }

    if (platform === 'unstop') {
      const source = root(response);
      for (const item of list(source?.data?.data || source?.data)) {
        const organisation = item.organisation || {};
        const locations = list(item.locations).map((location) =>
          typeof location === 'string' ? location : (location.name || location.city || '')
        ).filter(Boolean);

        jobs.push({
          platform: 'Unstop',
          id: String(item.id || item.short_id || item.public_url),
          title: item.title || '',
          company: organisation.name || item.company_name || '',
          location: locations.join(', ') || organisation.city || 'India',
          description: clean(item.jobDetail?.description || item.details || item.description),
          url: absolute(item.seo_url || item.public_url || item.short_url, 'https://unstop.com'),
          salary: item.salary || item.stipend || '',
          posted_date: item.approved_date || item.updated_at || '',
          job_type: item.type || 'Full-time',
          remote: JSON.stringify(item).toLowerCase().includes('remote'),
          required_skills: list(item.required_skills)
        });
      }
    }

    if (platform === 'arbeitnow') {
      for (const item of list(root(response)?.data)) {
        jobs.push({
          platform: 'Arbeitnow',
          id: String(item.slug || item.url),
          title: item.title || '',
          company: item.company_name || '',
          location: item.location || 'Europe',
          description: clean(item.description),
          url: item.url || '',
          salary: '',
          posted_date: item.created_at ? new Date(Number(item.created_at) * 1000).toISOString() : '',
          job_type: list(item.job_types).join(', ') || 'Full-time',
          remote: Boolean(item.remote),
          required_skills: list(item.tags)
        });
      }
    }

    if (platform === 'remoteok') {
      for (const item of flat(response).filter((entry) => entry.id && entry.position)) {
        jobs.push({
          platform: 'RemoteOK',
          id: String(item.id || item.slug),
          title: item.position || '',
          company: item.company || '',
          location: item.location || 'Remote',
          description: clean(item.description),
          url: item.apply_url || item.url || ('https://remoteok.com/l/' + item.id),
          salary: item.salary_min ? ('$' + item.salary_min + '-$' + item.salary_max) : '',
          posted_date: item.epoch ? new Date(Number(item.epoch) * 1000).toISOString() : (item.date || ''),
          job_type: 'Full-time',
          remote: true,
          required_skills: list(item.tags)
        });
      }
    }

    if (platform === 'himalayas') {
      for (const item of list(root(response)?.jobs)) {
        jobs.push({
          platform: 'Himalayas',
          id: String(item.guid || item.id || item.applicationLink),
          title: item.title || '',
          company: item.companyName || item.company?.name || '',
          location: list(item.locationRestrictions).join(', ') || 'Remote',
          description: clean(item.description || item.excerpt),
          url: item.applicationLink || item.applyUrl || item.url || '',
          salary: item.minSalary ? (String(item.currency || '$') + item.minSalary + '-' + item.maxSalary) : '',
          posted_date: item.pubDate || item.publishedAt || '',
          job_type: item.employmentType || item.jobType || 'Full-time',
          remote: true,
          required_skills: list(item.categories || item.skills)
        });
      }
    }

    if (platform === 'themuse') {
      for (const item of list(root(response)?.results)) {
        jobs.push({
          platform: 'The Muse',
          id: String(item.id || item.refs?.landing_page),
          title: item.name || '',
          company: item.company?.name || '',
          location: list(item.locations).map((location) => location.name).join(', ') || 'Remote',
          description: clean(item.contents),
          url: item.refs?.landing_page || '',
          salary: '',
          posted_date: item.publication_date || '',
          job_type: list(item.levels).map((level) => level.name).join(', ') || 'Entry Level',
          remote: list(item.locations).some((location) => String(location.name).toLowerCase().includes('remote')),
          required_skills: []
        });
      }
    }
  } catch (error) {
    console.log('Normalizer skipped ' + platform + ':', error.message);
  }
}

const normalized = jobs
  .filter((job) => job.id && job.title && job.company && job.url)
  .map((job) => ({
    json: {
      ...job,
      resumeData: context.resumeData,
      searchConfig: context.searchConfig,
      telegramChatId: context.telegramChatId,
      requestId: context.requestId
    }
  }));

return normalized.length ? normalized : [{
  json: {
    _empty: true,
    resumeData: context.resumeData,
    searchConfig: context.searchConfig,
    telegramChatId: context.telegramChatId,
    requestId: context.requestId
  }
}];

const context = $('Build Search Config').first().json;
const allJobs = $input.all().map((item) => item.json).filter((job) => !job._empty && job.title && job.company);
const technical = (context.resumeData.skills?.technical || []).map((skill) => String(skill).toLowerCase());
const titles = (context.searchConfig.titles || []).map((title) => String(title).toLowerCase());
const keywords = (context.searchConfig.keywords || []).map((keyword) => String(keyword).toLowerCase());
const prefersRemote = context.searchConfig.locations.some((location) => String(location).toLowerCase().includes('remote'));

const scored = allJobs.map((job) => {
  const title = String(job.title || '').toLowerCase();
  const description = String(job.description || '').toLowerCase();
  const required = (job.required_skills || []).map((skill) => String(skill).toLowerCase());
  let score = 0;

  for (const candidateTitle of titles) {
    const words = candidateTitle.split(/\s+/).filter((word) => word.length > 3);
    if (words.some((word) => title.includes(word))) score += 8;
  }

  for (const skill of technical.slice(0, 20)) {
    if (title.includes(skill) || description.includes(skill) || required.includes(skill)) score += 3;
  }

  for (const keyword of keywords) {
    if (title.includes(keyword) || description.includes(keyword)) score += 2;
  }

  if (prefersRemote && job.remote) score += 5;
  if (job.posted_date && new Date(job.posted_date) > new Date(Date.now() - 10 * 86400000)) score += 5;

  return { ...job, heuristic_score: score };
});

const seen = new Set();
const maxJobs = context.searchConfig.maxJobsForGemini || 30;
const aggregatedJobs = scored
  .sort((a, b) => b.heuristic_score - a.heuristic_score)
  .filter((job) => {
    const key = (job.title + '|' + job.company).toLowerCase().replace(/\s+/g, '');
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .slice(0, maxJobs);

return [{
  json: {
    aggregatedJobs,
    totalRaw: allJobs.length,
    resumeData: context.resumeData,
    searchConfig: context.searchConfig,
    telegramChatId: context.telegramChatId,
    requestId: context.requestId
  }
}];

const aggregate = $('Aggregate & Pre-Score Jobs').first().json;
const raw = $json.text || '{}';
let parsed = { scores: [], strategy: {} };

try {
  let cleaned = raw.trim();
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start !== -1 && end !== -1) cleaned = cleaned.substring(start, end + 1);
  parsed = JSON.parse(cleaned);
} catch (error) {
  console.log('Gemini score parser fallback used:', error.message);
}

const scoreMap = {};
for (const score of parsed.scores || []) {
  scoreMap[String(score.job_id)] = score;
}

const scoredJobs = aggregate.aggregatedJobs.map((job) => {
  const ai = scoreMap[String(job.id)] || {};
  const fallbackScore = Math.min(78, 35 + Number(job.heuristic_score || 0));
  const matchScore = Number.isFinite(Number(ai.match_score)) ? Number(ai.match_score) : fallbackScore;
  const priority = ai.application_priority || (matchScore >= 72 ? 'high' : (matchScore >= 52 ? 'medium' : 'low'));

  return {
    ...job,
    match_score: Math.max(0, Math.min(100, Math.round(matchScore))),
    match_reasons: ai.match_reasons || [],
    missing_skills: ai.missing_skills || [],
    strengths: ai.strengths || [],
    application_priority: priority,
    cover_letter_angle: ai.cover_letter_angle || '',
    red_flags: ai.red_flags || []
  };
});

const sorted = scoredJobs.sort((a, b) => b.match_score - a.match_score);
const highPriority = sorted.filter((job) => job.application_priority === 'high').slice(0, 10);
const mediumPriority = sorted.filter((job) => job.application_priority === 'medium').slice(0, 15);
const lowPriority = sorted.filter((job) => job.application_priority === 'low').slice(0, 10);
const topScores = sorted.slice(0, 20).map((job) => job.match_score);

return [{
  json: {
    jobs: {
      high_priority: highPriority,
      medium_priority: mediumPriority,
      low_priority: lowPriority
    },
    stats: {
      total_found: sorted.length,
      total_raw: aggregate.totalRaw,
      high_priority: highPriority.length,
      medium_priority: mediumPriority.length,
      low_priority: lowPriority.length,
      avg_match_score: topScores.length ? Math.round(topScores.reduce((sum, score) => sum + score, 0) / topScores.length) : 0,
      platforms_searched: [...new Set(sorted.map((job) => job.platform))]
    },
    careerStrategy: parsed.strategy || {},
    resumeData: aggregate.resumeData,
    searchConfig: aggregate.searchConfig,
    telegramChatId: aggregate.telegramChatId,
    requestId: aggregate.requestId
  }
}];

const jobs = $json.jobs || {};
const stats = $json.stats || {};
const strategy = $json.careerStrategy || {};

const careerStrategy = {
  executive_summary: strategy.executive_summary || (
    stats.total_found
      ? 'Review the highest-scoring roles first and apply with a short project-focused pitch.'
      : 'No matching jobs were returned by the public feeds in this run. Try again later as feeds refresh.'
  ),
  resume_improvements: strategy.resume_improvements || [],
  skill_gaps: strategy.skill_gaps || [],
  application_strategy: strategy.application_strategy || [],
  interview_prep_topics: strategy.interview_prep_topics || []
};

return [{
  json: {
    success: true,
    request_id: $json.requestId,
    generated_at: new Date().toISOString(),
    telegram_chat_id: $json.telegramChatId,
    candidate: $json.resumeData?.candidate || {},
    search_stats: stats,
    career_strategy: careerStrategy,
    jobs: {
      high_priority: jobs.high_priority || [],
      medium_priority: jobs.medium_priority || [],
      low_priority: jobs.low_priority || [],
      total_found: stats.total_found || 0
    },
    meta: {
      platforms_searched: stats.platforms_searched || [],
      configured_free_sources: ['Remotive', 'Unstop', 'Arbeitnow', 'RemoteOK', 'Himalayas', 'The Muse'],
      primary_search_query: $json.searchConfig?.primaryQuery || '',
      note: 'Uses public job feeds and Gemini 2.5 Flash-Lite. No paid job API is required.'
    }
  }
}];

return [{
  json: {
    ...$json,
    note: 'Run this workflow by sending /jobs to your Telegram bot once. That stores the chat ID automatically. Manual and daily runs can send messages after that.'
  }
}];

return [{
  json: {
    ...$json,
    note: 'No high-priority jobs were found in this run. Public feeds refresh regularly, so the next daily run may return new matches.'
  }
}];

